insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 30, 'Não tomará alguém a mulher de seu pai, nem descobrirá o colo de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 1, 'Não entrará na congregação do SENHOR o que tiver os testículos esmagados, nem o castrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 2, 'Não entrará bastardo na congregação do SENHOR: nem ainda na décima geração entrará na congregação do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 3, 'Não entrará amonita nem moabita na congregação do SENHOR; nem ainda na décima geração entrará na congregação do SENHOR para sempre:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 4, 'Porquanto não vos saíram a receber com pão e água ao caminho, quando saístes do Egito; e porque contratou contra ti a Balaão filho de Beor de Petor de Mesopotâmia da Síria, para que te amaldiçoasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 5, 'Mas não quis o SENHOR teu Deus ouvir a Balaão; e o SENHOR teu Deus te tornou a maldição em bênção, porque o SENHOR teu Deus te amava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 6, 'Não procurarás a paz deles nem seu bem em todos os dias para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 7, 'Não abominarás ao edomita, que teu irmão é: não abominarás ao egípcio, que estrangeiro foste em sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 8, 'Os filhos que nascerem deles, à terceira geração entrarão na congregação do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 9, 'Quando saíres a campanha contra teus inimigos, guarda-te de toda coisa má.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 10, 'Quando houver em ti alguém que não for limpo por acidente de noite, sairá do acampamento, e não entrará nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 11, 'E será que ao declinar da tarde se lavará com água, e quando for posto o sol, entrará no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 12, 'E terás um lugar fora do acampamento, e sairás ali fora;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 13, 'Terás também uma estaca entre tuas armas; e será que, quando estiveres ali fora, cavarás com ela, e logo ao voltar cobrirás teu excremento:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 14, 'Porque o SENHOR teu Deus anda por meio de teu acampamento, para livrar-te e entregar teus inimigos diante de ti; portanto será teu acampamento santo: para que ele não veja em ti coisa imunda, e se volte de trás de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 15, 'Não entregarás a seu senhor o servo que se fugir a ti de seu amo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 16, 'More contigo, em meio de ti, no lugar que escolher em alguma de tuas cidades, onde bem lhe estiver: não o oprimirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 17, 'Não haverá prostituta das filhas de Israel, nem haverá prostituto ritual dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 18, 'Não trarás pagamento de prostituta, nem pagamento de prostituto à casa do SENHOR teu Deus por nenhum voto; porque abominação é ao SENHOR teu Deus tanto um como o outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 19, 'Não tomarás de teu irmão juros de dinheiro, nem juros de comida, nem juros de coisa alguma que se costuma tomar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 20, 'Do estrangeiro tomarás juros, mas de teu irmão não o tomarás, para que te abençoe o SENHOR teu Deus em toda obra de tuas mãos sobre a terra à qual entras para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 21, 'Quando prometeres voto ao SENHOR teu Deus, não tardarás em pagá-lo; porque certamente o exigirá o SENHOR teu Deus de ti, e haveria em ti pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 22, 'Mas quando te abstiveres de prometer, não haverá em ti pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 23, 'Guardarás o que teus lábios pronunciarem; e farás, como prometeste ao SENHOR teu Deus, o que de tua vontade falaste por tua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 24, 'Quando entrares na vinha de teu próximo, comerás uvas até saciar teu desejo: mas não porás em teu vaso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 23, 25, 'Quando entrares na plantação de teu próximo, poderás cortar espigas com tua mão; mas não aplicarás foice à plantação de teu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 1, 'Quando algum tomar mulher e se casar com ela, se não lhe agradar por haver achado nela alguma coisa ofensiva, lhe escreverá carta de divórcio, e a entregará em sua mão, e a despedirá de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 2, 'E saída de sua casa, poderá ir e casar-se com outro homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 3, 'E se a aborrecer este último, e lhe escrever carta de divórcio, e a entregar em sua mão, e a despedir de sua casa; ou se morrer o posterior homem que a tomou para si por mulher,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 4, 'Não poderá seu primeiro marido, que a despediu, trazê-la de volta a tomar para que seja sua mulher, depois que foi contaminada; porque é abominação diante do SENHOR, e não hás de perverter a terra que o SENHOR teu Deus te dá por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 5, 'Quando tomar alguém mulher nova, não sairá à guerra, nem em nenhuma coisa se lhe ocupará; livre estará em sua casa por ano, para alegrar à sua mulher que tomou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 6, 'Não tomarás em penhor a pedra de moinho, nem a de baixo nem a de cima: porque seria penhorar a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 7, 'Quando for achado alguém que tenha furtado pessoa de seus irmãos os filhos de Israel, e houver comercializado com ela, ou a houver vendido, o tal ladrão morrerá, e tirarás o mal do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 8, 'Guarda-te de chaga de lepra, observando com empenho, e fazendo segundo tudo o que vos ensinarem os sacerdotes levitas: cuidareis de fazer como lhes mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 9, 'Lembra-te do que fez o SENHOR teu Deus a Miriã no caminho, depois que saístes do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 10, 'Quando deres a teu próximo alguma coisa emprestada, não entrarás em sua casa para tomar-lhe penhor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 11, 'Fora estarás, e o homem a quem emprestaste, te tirará fora o penhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 12, 'E se for homem pobre, não durmas com seu penhor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 13, 'Precisamente lhe devolverás o penhor quando o sol se ponha, para que durma em sua roupa, e te bendiga: e te será justiça diante do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 14, 'Não faças injustiça ao empregado pobre e necessitado, tanto de teus irmãos como de teus estrangeiros que estão em tua terra em tuas cidades:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 15, 'Em seu dia lhe darás seu salário, e não se porá o sol sem o dar a ele: pois é pobre, e com ele sustenta sua vida: para que não clame contra ti ao SENHOR, e seja em ti pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 16, 'Os pais não morrerão pelos filhos, nem os filhos pelos pais; cada um morrerá por seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 17, 'Não distorcerás o direito do peregrino e do órfão; nem tomarás por penhor a roupa da viúva:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 18, 'Mas lembra-te que foste servo no Egito, e dali te resgatou o SENHOR teu Deus: portanto, eu te mando que faças isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 19, 'Quando colheres tua plantação em teu campo, e esqueceres algum feixe no campo, não voltarás a tomá-lo: para o estrangeiro, para o órfão, e para a viúva será; para que te abençoe o SENHOR teu Deus em toda obra de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 20, 'Quando sacudires tuas olivas, não recorrerás os ramos atrás de ti: para o estrangeiro, para o órfão, e para a viúva será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 21, 'Quando vindimares tua vinha, não coletarás os restos de atrás de ti: para o estrangeiro, para o órfão, e para a viúva será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 24, 22, 'E lembra-te que foste servo na terra do Egito: portanto, eu te mando que faças isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 1, 'Quando houver pleito entre alguns, e vierem a juízo, e os julgarem, e absolverem ao justo e condenarem ao iníquo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 2, 'Será que, se o delinquente merecer ser açoitado, então o juiz o fará lançar em terra, e o fará açoitar diante de si, segundo seu delito, por conta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 3, 'Fará lhe dar quarenta açoites, não mais: não seja que, se o ferir com muitos açoites a mais destes, se humilhe teu irmão diante de teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 4, 'Não porás mordaça ao boi quando trilhar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 5, 'Quando irmãos estiverem juntos, e morrer algum deles, e não tiver filho, a mulher do morto não se casará fora com homem estranho: seu cunhado entrará a ela, e a tomará por sua mulher, e fará com ela parentesco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 6, 'E será que o primogênito que der à luz ela, se levantará em nome de seu irmão o morto, para que o nome deste não seja apagado de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 7, 'E se o homem não quiser tomar a sua cunhada, irá então a cunhada sua à porta aos anciãos, e dirá: Meu cunhado não quer suscitar nome em Israel a seu irmão; não quer aparentar-se comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 8, 'Então os anciãos daquela cidade o farão vir, e falarão com ele: e se ele se levantar, e disser, Não quero tomá-la,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 9, 'Então se aproximará sua cunhada a ele diante dos anciãos, e o descalçará o sapato de seu pé, e lhe cuspirá no rosto, e falará e dirá: Assim será feito ao homem que não edificar a casa de seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 10, 'E seu nome será chamado em Israel: A casa do descalço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 11, 'Quando alguns brigarem juntos um com o outro, e chegar a mulher de um para livrar a seu marido da mão do que lhe fere, e meter sua mão e lhe pegar por suas vergonhas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 12, 'Tu a cortarás então a mão, não a perdoará teu olho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 13, 'Não terás em tua bolsa peso grande e peso pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 14, 'Não terás em tua casa efa grande e efa pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 15, 'Pesos íntegros e justos terás; efa íntegro e justo terás: para que teus dias sejam prolongados sobre a terra que o SENHOR teu Deus te dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 16, 'Porque abominação é ao SENHOR teu Deus qualquer um que faz isto, qualquer um que faz injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 17, 'Lembra-te do que te fez Amaleque no caminho, quando saístes do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 18, 'Que te saiu ao caminho, e te desbaratou a retaguarda de todos os fracos que iam detrás de ti, quando tu estavas cansado e exausto; e não temeu a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 25, 19, 'Será, pois, quando o SENHOR teu Deus te houver dado repouso de teus inimigos ao redor, na terra que o SENHOR teu Deus te dá por herdar para que a possuas, que apagarás a memória de Amaleque de debaixo do céu: não te esqueças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 1, 'E será que, quando houveres entrado na terra que o SENHOR teu Deus te dá por herança, e a possuíres, e habitares nela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 2, 'Então tomarás das primícias de todos os frutos da terra, que tirares de tua terra que o SENHOR teu Deus te dá, e o porás em um cesto, e irás ao lugar que o SENHOR teu Deus escolher para fazer habitar ali seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 3, 'E chegarás ao sacerdote que for naqueles dias, e lhe dirás: Reconheço hoje ao SENHOR teu Deus que ei entrado na terra que jurou o SENHOR a nossos pais que nos havia de dar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 4, 'E o sacerdote tomará o cesto de tua mão, e o porá diante do altar do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 5, 'Então falarás e dirás diante do SENHOR teu Deus: Um arameu a ponto de perecer foi meu pai, o qual desceu ao Egito e peregrinou ali com poucos homens, e ali cresceu em gente grande, forte e numerosa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 6, 'E os egípcios nos maltrataram, e nos afligiram, e puseram sobre nós dura servidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 7, 'E clamamos ao SENHOR Deus de nossos pais; e ouviu o SENHOR nossa voz, e viu nossa aflição, e nosso sofrimento, e nossa opressão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 8, 'E tirou-nos o SENHOR do Egito com mão forte, e com braço estendido, e com grande espanto, e com sinais e com milagres:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 9, 'E trouxe-nos a este lugar, e deu-nos esta terra, terra que flui leite e mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 10, 'E agora, eis que, trouxe as primícias do fruto da terra que me deste, ó SENHOR. E o deixarás diante do SENHOR teu Deus, e te inclinarás diante do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 11, 'E te alegrarás com todo o bem que o SENHOR teu Deus houver dado a ti e a tua casa, tu e o levita, e o estrangeiro que está em meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 12, 'Quando houveres acabado de dizimar todo o dízimo de teus frutos no ano terceiro, o ano do dízimo, darás também ao levita, ao estrangeiro, ao órfão e à viúva; e comerão em tuas vilas, e se saciarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 13, 'E dirás diante do SENHOR teu Deus: Eu tirei o consagrado de minha casa, e também o dei ao levita, e ao estrangeiro, e ao órfão, e à viúva, conforme todos os teus mandamentos que me ordenaste: não transgredi teus mandamentos, nem me esqueci deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 14, 'Não comi disso em meu luto, nem tirei disso em impureza, nem disso dei para o morto: obedeci à voz do SENHOR meu Deus, fiz conforme tudo o que me mandaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 15, 'Olha desde a morada de tua santidade, desde o céu, e abençoa a teu povo Israel, e à terra que nos deste, como juraste a nossos pais, terra que flui leite e mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 16, 'O SENHOR teu Deus te manda hoje que cumpras estes estatutos e regulamentos; cuida, pois, de praticá-los com todo teu coração, e com toda tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 17, 'Ao SENHOR exaltou hoje para que te seja por Deus, e para andar em seus caminhos, e para guardar seus estatutos e seus mandamentos e seus regulamentos, e para ouvir sua voz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 18, 'E o SENHOR te exaltou hoje para que lhe sejas seu privativo povo, como ele te disse, e para que guardes todos os seus mandamentos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 26, 19, 'E para te pôr alto sobre todas as nações que fez, para louvor, e fama, e glória; e para que sejas povo santo ao SENHOR teu Deus, como ele disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 1, 'E mandou Moisés, com os anciãos de Israel, ao povo, dizendo: Guardareis todos os mandamentos que eu prescrevo hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 2, 'E será que, no dia que passardes o Jordão à terra que o SENHOR teu Deus te dá, te hás de levantar pedras grandes, as quais rebocarás com cal:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 3, 'E escreverás nelas todas as palavras desta lei, quando houveres passado para entrar na terra que o SENHOR teu Deus te dá, terra que flui leite e mel, como o SENHOR o Deus de teus pais te disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 4, 'Será pois, quando houveres passado o Jordão, que levantareis estas pedras que eu vos mando hoje, no monte de Ebal, e as rebocarás com cal:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 5, 'E edificarás ali altar ao SENHOR teu Deus, altar de pedras: não levantarás sobre elas ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 6, 'De pedras inteiras edificarás o altar do SENHOR teu Deus; e oferecerás sobre ele holocausto ao SENHOR teu Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 7, 'E sacrificarás ofertas pacíficas, e comerás ali; e te alegrarás diante do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 8, 'E escreverás nas pedras todas as palavras desta lei muito claramente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 9, 'E Moisés, com os sacerdotes levitas, falou a todo Israel, dizendo: Atende e escuta, Israel: hoje és feito povo do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 10, 'Ouvirás, pois, a voz do SENHOR teu Deus, e cumprirás seus mandamentos e seus estatutos, que eu te ordeno hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 11, 'E mandou Moisés ao povo naquele dia, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 12, 'Estes estarão sobre o monte de Gerizim para abençoar ao povo, quando houverdes passado o Jordão: Simeão, e Levi, e Judá, e Issacar, e José e Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 13, 'E estes estarão para pronunciar a maldição no de Ebal: Rúben, Gade, e Aser, e Zebulom, Dã, e Naftali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 14, 'E falarão os levitas, e dirão a todo homem de Israel em alta voz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 15, 'Maldito o homem que fizer escultura ou imagem de fundição, abominação ao SENHOR, obra da mão de artífice, e a puser em oculto. E todo o povo responderá e dirá: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 16, 'Maldito o que desonrar a seu pai ou a sua mãe. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 17, 'Maldito o que reduzir o termo de seu próximo. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 18, 'Maldito o que fizer errar ao cego no caminho. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 19, 'Maldito o que distorcer o direito do estrangeiro, do órfão, e da viúva. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 20, 'Maldito o que se deitar com a mulher de seu pai; porquanto revelou o colo de seu pai. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 21, 'Maldito o que tiver parte com qualquer animal. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 22, 'Maldito o que se deitar com sua irmã, filha de seu pai, ou filha de sua mãe. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 23, 'Maldito o que se deitar com sua sogra. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 24, 'Maldito o que ferir a seu próximo ocultamente. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 25, 'Maldito o que receber um presente para ferir de morte ao inocente. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 27, 26, 'Maldito o que não confirmar as palavras desta lei para as cumprir. E dirá todo o povo: Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 1, 'E será que, se ouvires com empenho a voz do SENHOR teu Deus, para guardar, para praticar todos os seus mandamentos que eu te prescrevo hoje, também o SENHOR teu Deus te porá alto sobre todas as nações da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 2, 'E virão sobre ti todas estas bênçãos, e te alcançarão, quando ouvires a voz do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 3, 'Bendito serás tu na cidade, e bendito tu no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 4, 'Bendito o fruto de teu ventre, e o fruto de teu animal, a cria de tuas vacas, e os rebanhos de tuas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 5, 'Bendito teu cesto e tua amassadeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 6, 'Bendito serás em teu entrar, e bendito em teu sair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 7, 'Causará o SENHOR a teus inimigos que se levantarem contra ti, que sejam derrotados diante de ti: por um caminho sairão a ti, por sete caminhos fugirão diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 8, 'Enviará o SENHOR contigo a bênção em teus granários, e em tudo aquilo em que puseres tua mão; e te abençoará na terra que o SENHOR teu Deus te dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 9, 'O SENHOR te confirmará por povo seu santo, como te jurou, quando guardares os mandamentos do SENHOR teu Deus, e andares em seus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 10, 'E verão todos os povos da terra que o nome do SENHOR é chamado sobre ti, e te temerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 11, 'E te fará o SENHOR superabundar em bens, no fruto de teu ventre, e no fruto de teu animal, e no fruto de tua terra, na terra que o SENHOR jurou aos teus pais que te havia de dar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 12, 'O SENHOR te abrirá seu bom depósito, o céu, para dar chuva à tua terra em seu tempo, e para abençoar toda obra de tuas mãos. E emprestarás a muitas nações, e tu não tomarás emprestado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 13, 'E te porá o SENHOR por cabeça, e não por cauda: e estarás encima somente, e não estarás debaixo; quando obedeceres aos mandamentos do SENHOR teu Deus, que eu te ordeno hoje, para que os guardes e cumpras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 14, 'E não te desvies de todas as palavras que eu vos mando hoje, nem à direita nem à esquerda, para ir atrás de deuses alheios para servir-lhes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 15, 'E será, se não ouvires a voz do SENHOR teu Deus, para cuidar de praticar todos os seus mandamentos e seus estatutos, que eu te intimo hoje, que virão sobre ti todas estas maldições, e te alcançarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 16, 'Maldito serás tu na cidade, e maldito no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 17, 'Maldito teu cesto, e tua amassadeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 18, 'Maldito o fruto de teu ventre, e o fruto de tua terra, e a cria de tuas vacas, e os rebanhos de tuas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 19, 'Maldito serás em teu entrar, e maldito em teu sair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 20, 'E o SENHOR enviará contra ti a maldição, confusão e oposição em tudo quanto puseres mão e fizeres, até que sejas destruído, e pereças logo por causa da maldade de tuas obras, pelas quais me houverdes deixado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 21, 'O SENHOR fará que se te pegue mortandade, até que te consuma da terra à qual entras para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 22, 'O SENHOR te ferirá de tísica, e de febre, e de ardor, e de calor, e de espada, e de calamidade repentina, e com mofo; e te perseguirão até que pereças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 23, 'E teus céus que estão sobre tua cabeça, serão de bronze; e a terra que está debaixo de ti, de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 24, 'Dará o SENHOR por chuva à tua terra pó e cinza: dos céus descerão sobre ti até que pereças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 25, 'O SENHOR te entregará ferido diante de teus inimigos: por um caminho sairás a eles, e por sete caminhos fugirás diante deles: e serás sacudido a todos os reinos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 26, 'E será teu corpo morto por comida a toda ave do céu, e animal da terra, e não haverá quem as espante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 27, 'O SENHOR te ferirá da praga do Egito, e com tumores, e com sarna, e com coceira, de que não possas ser curado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 28, 'O SENHOR te ferirá com loucura, e com cegueira, e com confusão de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 29, 'E apalparás ao meio-dia, como apalpa o cego na escuridão, e não serás próspero em teus caminhos: e nunca serás a não ser somente oprimido e roubado todos os dias, e não haverá quem te salve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 30, 'Tu te casarás com mulher, e outro homem dormirá com ela; edificarás casa, e não habitarás nela; plantarás vinha, e não a vindimarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 31, 'Teu boi será matado diante de teus olhos, e tu não comerás dele; teu asno será arrebatado de diante de ti, e não se te voltará; tuas ovelhas serão dadas a teus inimigos, e não terás quem te as resgate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 32, 'Teus filhos e tuas filhas serão entregues a outro povo, e teus olhos o verão, e desfalecerão por eles todo o dia: e não haverá força em tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 33, 'O fruto de tua terra e todo teu trabalho comerá povo que não conheceste; e nunca serás a não ser somente oprimido e quebrantado todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 34, 'E enlouquecerás por causa do que verás com teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 35, 'O SENHOR te ferirá com maligna úlcera nos joelhos e nas pernas, sem que possas ser curado: ainda desde a planta de teu pé até o topo de tua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 36, 'O SENHOR levará a ti, e a teu rei que houveres posto sobre ti, a nação que não conheceste tu nem teus pais; e ali servirás a deuses alheios, à madeira e à pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 37, 'E serás por confusão, por exemplo e por fábula, a todos os povos aos quais te levará o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 38, 'Tirarás muito semente ao campo, e colherás pouco; porque os gafanhotos o consumirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 39, 'Plantarás vinhas e lavrarás, mas não beberás vinho, nem colherás uvas; porque o bicho as comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 40, 'Terás olivas em todo teu termo, mas não te ungirás com o azeite; porque tua azeitona cairá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 41, 'Filhos e filhas gerarás, e não serão para ti; porque irão em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 42, 'Todo o teu arvoredo e o fruto de tua terra os gafanhotos consumirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 43, 'O estrangeiro que estará em meio de ti subirá sobre ti muito alto, e tu serás posto muito abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 44, 'Ele emprestará a ti, e tu não emprestarás a ele: ele será por cabeça, e tu serás por cauda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 45, 'E virão sobre ti todas estas maldições, e te perseguirão, e te alcançarão até que pereças; porquanto não houverdes atendido à voz do SENHOR teu Deus, para guardar seus mandamentos e seus estatutos, que ele te mandou:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 46, 'E serão em ti por sinal e por maravilha, e em tua descendência para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 47, 'Porquanto não serviste ao SENHOR teu Deus com alegria e com alegria de coração, pela abundância de todas as coisas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 48, 'Servirás, portanto, a teus inimigos que enviar o SENHOR contra ti, com fome e com sede e com nudez, e com falta de todas as coisas; e ele porá jugo de ferro sobre teu pescoço, até destruir-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 49, 'O SENHOR trará sobre ti nação de longe, do extremo da terra, que voe como água, nação cuja língua não entendas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 50, 'Nação feroz de rosto, que não terá respeito ao ancião, nem perdoará à criança:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 51, 'E comerá o fruto de teu animal e o fruto de tua terra, até que pereças: e não te deixará grão, nem mosto, nem azeite, nem a cria de tuas vacas, nem os rebanhos de tuas ovelhas, até destruir-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 52, 'E te porá cerco em todas as tuas cidades, até que caiam teus muros altos e fortificados em que tu confias, em toda tua terra: te cercará, pois, em todas tuas cidades e em toda tua terra, que o SENHOR teu Deus te houver dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 53, 'E comerás o fruto de teu ventre, a carne de teus filhos e de tuas filhas que o SENHOR teu Deus te deu, no cerco e nos apuros com que te angustiará teu inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 54, 'O homem tenro em ti, e o muito delicado, seu olho será maligno para com seu irmão, e para com a mulher de seu seio, e para com o resto de seus filhos que lhe restarem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 55, 'Para não dar a algum deles da carne de seus filhos, que ele comerá, porque nada lhe haverá restado, no cerco e nos apuros com que teu inimigo te oprimirá em todas tuas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 56, 'A tenra e a delicada entre vós, que nunca a planta de seu pé provou a sentar sobre a terra, de ternura e delicadeza, seu olho será maligno para com o marido de seu seio, e para com seu filho, e para com sua filha,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 57, 'E para com sua criança que sai dentre seus pés, e para com seus filhos que der à luz; pois os comerá ocultamente, a falta de tudo, no cerco e em apuros com que teu inimigo te oprimirá em tuas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 58, 'Se não cuidares de praticar todas as palavras desta lei que estão escritas neste livro, temendo este nome glorioso e terrível, O SENHOR TEU DEUS,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 59, 'O SENHOR aumentará maravilhosamente tuas pragas e as pragas de tua descendência, pragas grandes e duradouras, e enfermidades malignas e duradouras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 60, 'E fará voltar sobre ti todos os males do Egito, diante dos quais temeste, e se te pegarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 61, 'Assim como toda enfermidade e toda praga que não está escrita no livro desta lei, o SENHOR a enviará sobre ti, até que tu sejas destruído.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 62, 'E restareis em pouca gente, em lugar de haver sido como as estrelas do céu em multidão; porquanto não obedeceste à voz do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 63, 'E será que como o SENHOR se alegrou sobre vós para fazer-vos bem, e para multiplicar-vos, assim se alegrará o SENHOR sobre vós para vos arruinar, e para destruir-vos; e sereis tirados de sobre a terra, à qual entrais para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 64, 'E o SENHOR te espalhará por todos os povos, desde um extremo da terra até o outro extremo dela; e ali servirás a deuses alheios que não conheceste tu nem teus pais, à madeira e à pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 65, 'E nem ainda entre as mesmas nações descansarás, nem a planta de teu pé terá repouso; que ali te dará o SENHOR coração temeroso, e caimento de olhos, e tristeza de alma:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 66, 'E terás tua vida como suspensa diante de ti, e estarás temeroso de noite e de dia, e não confiarás de tua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 67, 'Pela manhã dirás: Quem dera fosse a tarde! E à tarde dirás: Quem dera fosse a manhã! pelo medo de teu coração com que estarás amedrontado, e pelo que verão teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 28, 68, 'E o SENHOR te fará voltar ao Egito em navios pelo caminho do qual te disse: Nunca mais voltareis: e ali sereis vendidos a vossos inimigos por escravos e por escravas, e não haverá quem vos compre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 1, 'Estas são as palavras do pacto que o SENHOR mandou que Moisés fizesse com os filhos de Israel na terra de Moabe, além do pacto que estabeleceu com eles em Horebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 2, 'Moisés, pois, chamou a todo Israel, e disse-lhes: Vós vistes tudo o que o SENHOR fez diante vossos olhos na terra do Egito a Faraó e a todos os seus servos, e a toda sua terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 3, 'As provas grandes que viram teus olhos, o sinais, e as grandes maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 4, 'E o SENHOR não vos deu coração para entender, nem olhos para ver, nem ouvidos para ouvir, até o dia de hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 5, 'E eu vos trouxe quarenta anos pelo deserto: vossas roupas não se hão envelhecido sobre vós, nem teu sapato se envelheceu sobre teu pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 6, 'Não comestes pão, nem bebestes vinho nem bebida forte: para que soubestes que eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 7, 'E chegastes a este lugar, e saiu Seom rei de Hesbom, e Ogue rei de Basã, diante de nós para lutar, e os ferimos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 8, 'E tomamos sua terra, e a demos por herança a Rúben e a Gade, e à meia tribo de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 9, 'Guardareis, pois, as palavras deste pacto, e as poreis por obra, para que prospereis em tudo o que fizerdes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 10, 'Vós todos estais hoje diante do SENHOR vosso Deus; vossos príncipes de vossas tribos, vossos anciãos, e vossos oficiais, todos os homens de Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 11, 'Vossas crianças, vossas mulheres, e teus estrangeiros que habitam em meio de teu campo, desde o que corta tua lenha até o que tira tuas águas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 12, 'Para que entres no pacto do SENHOR teu Deus, e em seu juramento, que o SENHOR teu Deus estabelece hoje contigo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 13, 'Para te confirmar hoje por seu povo, e que ele seja a ti por Deus, da maneira que ele te disse, e como ele jurou a teus pais Abraão, Isaque, e Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 14, 'E não somente convosco estabeleço eu este pacto e este juramento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 15, 'Mas, sim, com os que estão aqui presentes hoje conosco diante do SENHOR nosso Deus, e com os que não estão aqui hoje conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 16, 'Porque vós sabeis como habitamos na terra do Egito, e como passamos por meio das nações que passastes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 17, 'E vistes suas abominações e seus ídolos, madeira e pedra, prata e ouro, que têm consigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 18, 'Para que não haja entre vós homem, ou mulher, ou família, ou tribo, cujo coração se volte hoje de com o SENHOR nosso Deus, por andar a servir aos deuses daquelas nações; que não haja em vós raiz que lance veneno e amargura;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 19, 'E seja que, quando o tal ouvir as palavras desta maldição, ele se abençoe em seu coração, dizendo: Terei paz, ainda que ande segundo o pensamento de meu coração, para acrescentar a embriaguez à sede:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 20, 'O SENHOR se recusará a lhe perdoar; antes fumegará logo o furor do SENHOR e seu zelo sobre o tal homem, e se assentará sobre ele toda maldição escrita neste livro, e o SENHOR apagará seu nome de debaixo do céu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 21, 'E o SENHOR o separará de todas as tribos de Israel para o mal, conforme todas as maldições do pacto escrito neste livro da lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 22, 'E dirá a geração vindoura, vossos filhos que virão depois de vós, e o estrangeiro que virá de distantes terras, quando virem as pragas desta terra, e suas enfermidades de que o SENHOR a fez enfermar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 23, '(Enxofre e sal, abrasada toda sua terra: não será semeada, nem produzirá, nem crescerá nela erva nenhuma, como na destruição de Sodoma e de Gomorra, de Admá e de Zeboim, que o SENHOR destruiu em seu furor e em sua ira:)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 24, 'Dirão, pois, todas as nações: Por que fez o SENHOR isto a esta terra? Que ira é esta de tão grande furor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 25, 'E responderão. Porquanto deixaram o pacto do SENHOR o Deus de seus pais, que ele estabeleceu com eles quando os tirou da terra do Egito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 26, 'E foram e serviram a deuses alheios, e inclinaram-se a eles, deuses que não conheciam, e que nenhuma coisa lhes haviam dado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 27, 'Acendeu-se portanto, o furor do SENHOR contra esta terra, para trazer sobre ela todas as maldições escritas nesta livro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 28, 'E o SENHOR os desarraigou de sua terra com ira, e com indignação, e com furor grande, e os expulsou a outra terra, como hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 29, 29, 'As coisas secretas pertencem ao SENHOR nosso Deus: mas as reveladas são para nós e para nossos filhos para sempre, para que cumpramos todas as palavras desta lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 1, 'E será que, quando te sobrevierem todas estas coisas, a bênção e a maldição que pus diante de ti, e te conscientizares em teu coração em meio de todas as nações às quais o SENHOR teu Deus te houver expulsado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 2, 'E te converteres ao SENHOR teu Deus, e obedeceres à sua voz conforme tudo o que eu te mando hoje, tu e teus filhos, com todo teu coração e com toda tua alma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 3, 'O SENHOR te restaurará de teu infortúnio, terá misericórdia de ti, e voltará a recolher-te de todos os povos aos quais o SENHOR, teu Deus, te houver disperso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 4, 'Se houveres sido lançado até a extremidade dos céus, dali te recolherá o SENHOR teu Deus, e dali te tomará:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 5, 'E te fará voltar o SENHOR teu Deus à terra que herdaram teus pais, e a possuirás; e te fará bem, e te multiplicará mais que a teus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 6, 'E circuncidará o SENHOR teu Deus teu coração, e o coração de tua descendência, para que ames ao SENHOR teu Deus com todo teu coração e com toda tua alma, a fim de que tu vivas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 7, 'E porá o SENHOR teu Deus todas estas maldições sobre teus inimigos, e sobre teus aborrecedores que te perseguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 8, 'E tu voltarás, e ouvirás a voz do SENHOR, e porás por obra todos os seus mandamentos, que eu te intimo hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 9, 'E te fará o SENHOR teu Deus abundar em toda obra de tuas mãos, no fruto de teu ventre, no fruto de teu animal, e no fruto de tua terra, para o bem: porque o SENHOR voltará a se alegrar sobre ti para o bem, da maneira que se alegrou sobre teus pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 10, 'Quando ouvires a voz do SENHOR teu Deus, para guardar seus mandamentos e seus estatutos escritos neste livro da lei; quando te converteres ao SENHOR teu Deus com todo teu coração e com toda tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 11, 'Porque este mandamento que eu te intimo hoje, não te é encoberto, nem está longe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 12, 'Não está no céu, para que digas: Quem subirá por nós ao céu, e nos o trará e o apresentará para nós, para que o cumpramos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 13, 'Nem está da outra parte do mar, para que digas: Quem passará por nós o mar, para que o traga até nós e a nós o apresente, a fim de que o cumpramos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 14, 'Porque muito próxima de ti está a palavra, em tua boca e em teu coração, para que a cumpras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 15, 'Olha, eu pus diante de ti hoje a vida e o bem, a morte e o mal:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 16, 'Porque eu te mando hoje que ames ao SENHOR teu Deus, que andes em seus caminhos, e guardes seus mandamentos e seus estatutos e seus regulamentos, para que vivas e sejas multiplicado, e o SENHOR teu Deus te abençoe na terra à qual entras para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 17, 'Mas se teu coração se desviar, e não ouvires, e fores incitado, e te inclinares a deuses alheios, e os servires;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 18, 'Declaro-vos hoje que certamente perecereis: não tereis longos dias sobre a terra, para ir à qual passas o Jordão para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 19, 'Aos céus e a terra chamo por testemunhas hoje contra vós, que pus diante de vós a vida e a morte, a bênção e a maldição: escolhe, pois, a vida, para que vivas tu e tua descendência:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 30, 20, 'Que ames ao SENHOR teu Deus, que ouças sua voz, e te achegues a ele; porque ele é tua vida, e o comprimento de teus dias; a fim de que habites sobre a terra que jurou o SENHOR a teus pais Abraão, Isaque, e Jacó, que lhes havia de dar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 1, 'E foi Moisés, e falou estas palavras a todo Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 2, 'E disse-lhes: De idade de cento e vinte anos sou hoje dia; não posso mais sair nem entrar: a mais disto o SENHOR me disse: Não passarás este Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 3, 'O SENHOR teu Deus, ele passa diante de ti; ele destruirá estas nações de diante de ti, e as herdarás: Josué será o que passará diante de ti, como o SENHOR disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 4, 'E fará o SENHOR com eles como fez com Seom e com Ogue, reis dos amorreus, e com sua terra, que os destruiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 5, 'E os entregará o SENHOR diante de vós, e fareis com eles conforme tudo o que vos mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 6, 'Esforçai-vos e tende ânimo; não temais, nem tenhais medo deles: que o SENHOR teu Deus é o que vai contigo: não te deixará nem te desamparará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 7, 'E chamou Moisés a Josué, e disse-lhe à vista de todo Israel: Esforça-te e anima-te; porque tu entrarás com este povo à terra que jurou o SENHOR a seus pais que lhes havia de dar, e tu a farás herdar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 8, 'E o SENHOR é o que vai diante de ti; ele será contigo, não te deixará, nem te desamparará; não temas, nem te intimides.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 9, 'E escreveu Moisés esta lei, e deu-a aos sacerdotes, filhos de Levi, que levavam a arca do pacto do SENHOR, e a todos os anciãos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 10, 'E mandou-lhes Moisés, dizendo: Ao fim do sétimo ano, no ano da remissão, na festa das cabanas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 11, 'Quando vier todo Israel a apresentar-se diante do SENHOR teu Deus no lugar que ele escolher, lerás esta lei diante de todo Israel aos ouvidos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 12, 'Farás congregar o povo, homens e mulheres e crianças, e teus estrangeiros que estiverem em tuas cidades, para que ouçam e aprendam, e temam ao SENHOR vosso Deus, e cuidem de praticar todas as palavras desta lei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 13, 'E os filhos deles que não souberem ouçam, e aprendam a temer ao SENHOR vosso Deus todos os dias que viverdes sobre a terra, para ir à qual passais o Jordão para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 14, 'E o SENHOR disse a Moisés: Eis que se aproximam teus dias para que morras: chama a Josué, e esperai no tabernáculo do testemunho, e lhe mandarei. Foram pois Moisés e Josué, e esperaram no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 15, 'E apareceu-se o SENHOR no tabernáculo, na coluna de nuvem; e a coluna de nuvem se pôs sobre a porta do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 16, 'E o SENHOR disse a Moisés: Eis que tu vais descansar com teus pais, e este povo se levantará e se prostituirá atrás dos deuses alheios da terra aonde vai, em estando em meio dela; e me deixará, e invalidará meu pacto que estabeleci com ele:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 17, 'E meu furor se acenderá contra ele naquele dia; e os abandonarei, e esconderei deles meu rosto, e serão consumidos; e o acharão muitos males e angústias, e dirá naquele dia: Não me acharam estes males porque não está meu Deus em meio de mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 18, 'Porém eu esconderei certamente meu rosto naquele dia, por todo o mal que eles houverem feito, por haver-se voltado a deuses alheios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 19, 'Agora, pois, escrevei-vos este cântico, e ensina-o aos filhos de Israel: põe-o em boca deles, para que este cântico me seja por testemunha contra os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 20, 'Porque eu lhe introduzirei na terra que jurei a seus pais, a qual flui leite e mel; e comerá, e se fartará, e se engordará: e se voltarão a deuses alheios, e lhes servirão, e me provocarão à ira, e invalidarão meu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 21, 'E será que quando lhe vierem muitos males e angústias, então responderá em sua face este cântico como testemunha, pois não cairá em esquecimento da boca de sua linhagem: porque eu conheço seu intento, e o que faz hoje antes que lhe introduza na terra que jurei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 22, 'E Moisés escreveu este cântico aquele dia, e ensinou-o aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 23, 'E deu ordem a Josué filho de Num, e disse: Esforça-te e anima-te, que tu porás os filhos de Israel na terra que lhes jurei, e eu serei contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 24, 'E quando acabou Moisés de escrever as palavras desta lei em um livro até concluir,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 25, 'Mandou Moisés aos levitas que levavam a arca do pacto do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 26, 'Tomai este livro da lei, e ponde-o ao lado da arca do pacto do SENHOR vosso Deus, e esteja ali por testemunha contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 27, 'Porque eu conheço tua rebelião, e tua dura cerviz: eis que ainda vivendo eu hoje convosco, sois rebeldes ao SENHOR; e quanto mais depois que eu morrer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 28, 'Congregai a mim todos os anciãos de vossas tribos, e a vossos oficiais, e falarei em seus ouvidos estas palavras, e chamarei por testemunhas contra eles os céus e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 29, 'Porque eu sei que depois de minha morte, certamente vos corrompereis e vos desviareis do caminho que vos mandei; e que vos há de vir mal nos últimos dias, por haver feito mal aos olhos do SENHOR, provocando-lhe à ira com a obra de vossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 31, 30, 'Então falou Moisés aos ouvidos de toda a congregação de Israel as palavras deste cântico até acabá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 1, 'Escutai, céus, e falarei; E ouça a terra os ditos de minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 2, 'Gotejará como a chuva minha doutrina; Destilará como o orvalho meu discurso; Como o chuvisco sobre a grama, E como as gotas sobre a erva:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 3, 'Porque invocarei o nome do SENHOR; Engrandecei ao nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 4, '[Ele é] a Rocha, sua obra é perfeita, pois todos os seus caminhos são justos. Deus fiel, e sem imoralidade; justo e correto ele é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 5, 'Corromperam-se contra ele; não são seus filhos, a falha é deles. São uma geração perversa e distorcida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 6, 'É assim que pagais ao SENHOR, ó povo tolo e insensato? Não é ele teu pai que te adquiriu, te fez, e te estabeleceu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 7, 'Lembra-te dos tempos antigos; Considerai os anos de geração e geração: Pergunta a teu pai, que ele te declarará; A teus anciãos, e eles te dirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 8, 'Quando o Altíssimo fez herdar às nações, Quando fez dividir os filhos dos homens, Estabeleceu os termos dos povos Segundo o número dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 9, 'Porque a parte do SENHOR é seu povo; Jacó a medida de sua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 10, 'Achou-o em terra de deserto, E em deserto horrível e ermo; Cercou-o, instruiu-o, Guardou-o como a menina de seu olho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 11, 'Como a água desperta sua ninhada, paira sobre seus passarinhos, estende suas asas, os toma, os leva sobre suas penas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 12, 'o SENHOR sozinho o guiou, e nenhum deus estrangeiro esteve com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 13, 'Ele o fez cavalgar sobre os lugares altos da terra; alimentou-o com os frutos do campo, e o fez sugar mel da rocha e azeite da dura pederneira;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 14, 'manteiga de vacas e leite de ovelhas, com gordura de cordeiros, e carneiros de Basã; também machos de bode, com o melhor do trigo; e bebeste o sangue das uvas, o vinho puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 15, 'E engordou Jesurum, e deu coices: engordaste-te, engrossaste-te, cobriste-te: e deixou ao Deus que lhe fez, e menosprezou a Rocha de sua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 16, 'Provocaram-lhe ciúmes com os deuses alheios; irritaram-lhe com abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 17, 'Sacrificaram aos demônios, não a Deus; a deuses que não conheciam, a novos deuses vindos de perto, Que não haviam temido vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 18, 'Abandonaste a Rocha que te gerou; e te esqueceste do Deus que te criou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 19, 'E o SENHOR o viu, e acendeu-se em ira, pelo menosprezo de seus filhos e de suas filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 20, 'E disse: esconderei deles meu rosto, verei qual será seu fim; pois são geração de perversidades, filhos sem fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 21, 'Eles me provocaram ciúmes com o que não é Deus; com suas vaidades provocaram-me à ira; eu também provocarei os ciúmes com aqueles que não são povo, e com uma nação insensata eu os provocarei à ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 22, 'Porque um fogo se acendeu em meu furor, e arderá até as profundezas do Xeol; e consumirá a terra e seus frutos, e abrasará os fundamentos dos montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 23, 'Eu trarei males sobre eles; gastarei neles minhas flechas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 24, 'Consumidos serão de fome, e comidos de febre ardente E de amarga pestilência; Dente de animais enviarei também sobre eles, Com veneno de serpente da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 25, 'De fora desolará a espada, E dentro das câmaras o espanto: Tanto ao rapaz como à virgem, Ao que mama como o homem grisalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 26, 'Disse: Eu os dispersaria do mundo, Faria cessar dentre os homens a memória deles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 27, 'Se não temesse a ira do inimigo, Não seja que se envaideçam seus adversários, Não seja que digam: Nossa mão alta fez tudo isto, não o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 28, 'Porque são gente de perdidos conselhos, E não há neles entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 29, 'Bom seria se fossem sábios, que compreendessem isto, E entendessem seu fim!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 30, 'Como poderia perseguir um a mil, E dois fariam fugir a dez mil, Se sua Rocha não os houvesse vendido, E o SENHOR não os houvesse entregue?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 31, 'Que a rocha deles não é como nossa Rocha: E nossos inimigos sejam disso juízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 32, 'Porque da vide de Sodoma é a vide deles, E dos sarmentos de Gomorra: As uvas deles são uvas venenosas, cachos muito amargos têm.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 33, 'Veneno de serpentes é seu vinho, e peçonha cruel de áspides.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 34, 'Não tenho eu isto guardado, Selado em meus tesouros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 35, 'Minha é a vingança e o pagamento, Ao tempo que seu pé vacilará; Porque o dia de sua aflição está próximo, E o que lhes está preparado se apressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 36, 'Porque o SENHOR julgará a seu povo, E por causa de seus servos se arrependerá, Quando vir que a força pereceu, E que não há prisioneiro nem livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 37, 'E dirá: Onde estão seus deuses, A rocha em que se refugiavam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 38, 'Que comiam a gordura de seus sacrifícios, Bebiam o veio de suas libações? Levante-se, que vos ajudem E vos defendam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 39, 'Vede agora que Eu, Eu Sou, e não há deus além de mim; eu trago a morte, e eu faço viver; eu firo, e eu curo; e não há quem possa escapar da minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 40, 'Quando eu erguer aos céus minha mão, e disser: “Tão certo como eu vivo para sempre”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 41, 'Se eu afiar minha espada reluzente, e minha mão agarrar o juízo, devolverei a vingança sobre os meus adversários, e retribuirei aos que me odeiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 42, 'Embriagarei de sangue minhas flechas, e minha espada devorará carne, no sangue dos mortos e dos cativos, das cabeças dos líderes inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 43, 'Jubilai, ó nações, com o povo dele, porque ele vingará o sangue dos seus servos, e devolverá a vingança sobre os seus inimigos, e expiará sua terra, pelo seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 44, 'E Moisés veio, e recitou todas as palavras deste cântico aos ouvidos do povo, ele, e Josué filho de Num.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 45, 'E acabou Moisés de recitar todas estas palavras a todo Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 46, 'E disse-lhes: Ponde vosso coração a todas as palavras que eu vos declaro hoje, para que as mandeis a vossos filhos, e cuidem de praticar todas as palavras desta lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 47, 'Porque não vos é coisa vã, mas é vossa vida: e por elas fareis prolongar os dias sobre a terra, para possuir a qual passais o Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 48, 'E falou o SENHOR a Moisés aquele mesmo dia, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 49, 'Sobe a este monte de Abarim, ao monte Nebo, que está na terra de Moabe, que está em frente de Jericó, e olha a terra de Canaã, que eu dou por herança aos filhos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 50, 'E morre no monte ao qual sobes, e sê reunido a teus povos; ao modo que morreu Arão teu irmão no monte de Hor, e foi reunido a seus povos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 51, 'Porquanto transgredistes contra mim em meio dos filhos de Israel nas águas da briga de Cades, no deserto de Zim; porque não me santificastes em meio dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 32, 52, 'Verás, portanto, diante de ti a terra; mas não entrarás ali, à terra que dou aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 1, 'E esta é a bênção com a qual abençoou Moisés homem de Deus aos filhos de Israel, antes que morresse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 2, 'E disse: O SENHOR veio de Sinai, E de Seir lhes iluminou; Resplandeceu do monte de Parã, E veio com dez mil santos: À sua direita a lei de fogo para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 3, 'Ainda amou os povos; Todos seus santos em tua mão: Eles também se chegaram a teus pés: Receberam de teus ditos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 4, 'Lei nos mandou Moisés, Herança à congregação de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 5, 'E foi rei em Jesurum, quando se congregaram os chefes do povo com as tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 6, 'Viva Rúben, e não morra; sejam seus homens em número.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 7, 'E esta bênção para Judá. Disse assim: Ouve, ó SENHOR, a voz de Judá, e leva-o ao seu povo; suas mãos lhe bastem, e tu sejas ajuda contra seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 8, 'E a Levi disse: Teu Tumim e teu Urim, com teu bom homem ao qual tentaste em Massá, e lhe fizeste brigar nas águas da briga;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 9, 'O que disse a seu pai e a sua mãe: Nunca os vi: nem conheceu a seus irmãos, nem conheceu a seus filhos; por isso eles guardarão as tuas palavras, e observarão o teu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 10, 'Eles ensinarão teus juízos a Jacó, e tua lei a Israel; porão o incenso diante de ti, e holocaustos sobre o teu altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 11, 'Abençoa, ó SENHOR, o que fizerem, e recebe com agrado a obra de suas mãos; fere os lombos de seus inimigos, e dos que lhe odiarem; para que nunca se levantem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 12, 'E a Benjamim disse: O amado do SENHOR habitará confiante próximo dele; Ele o cobrirá sempre, E entre seus ombros morará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 13, 'E a José disse: Bendita do SENHOR [seja] a sua terra, com as dádivas dos céus, com o orvalho, e com o abismo que jaz abaixo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 14, 'com excelentes frutos do sol, e com os excelentes produtos de cada lua,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 15, 'e com o que há de mais excelente dos montes antigos, e com os excelentes produtos das colinas eternas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 16, 'e com os excelentes produtos da terra e sua plenitude; e que a benevolência daquele que habitou na sarça venha sobre a cabeça de José, e sobre ao topo da cabeça do que foi separado dos seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 17, 'Ele é preeminente como o primogênito de seu touro, e suas pontas, chifres de boi selvagem; com eles chifrará os povos juntamente até os confins da terra; e estes são as dezenas de milhares de Efraim, e estes os milhares de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 18, 'E a Zebulom disse: Alegra-te, Zebulom, quando saíres; e tu Issacar, em tuas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 19, 'Eles chamarão os povos ao monte; ali oferecerão sacrifícios de justiça; porque sugarão a abundância dos mares, e os tesouros escondidos da areia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 20, 'E a Gade disse: Bendito o que fez alargar a Gade: Como leão habitará, e arrebatará braço e testa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 21, 'E ele se proveu da primeira parte, porque ali uma porção do legislador foi-lhe reservada, e veio na dianteira do povo; executará a justiça do SENHOR, e seus juízos com Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 22, 'E a Dã disse: Dã [é] um leão jovem; saltará desde Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 23, 'E a Naftali disse: Naftali, saciado de benevolência, e cheio da bênção do SENHOR, possui o ocidente e o sul,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 24, 'E a Aser disse: Bendito [seja] Aser em filhos; agradável será aos seus irmãos, e molhará em azeite o seu pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 25, 'ferro e bronze [será] o teu calçado, e tua força [será] como os teus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 26, 'Não há como o Deus de Jesurum, montado sobre os céus para tua ajuda, e sobre as nuvens com sua grandeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 27, 'O eterno Deus é o teu refúgio, e abaixo os braços eternos; ele expulsará de diante de ti o inimigo, e dirá: Destrói.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 28, 'E Israel, fonte de Jacó, habitará confiante sozinho na terra do grão e do vinho; também seus céus destilarão orvalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 33, 29, 'Bem-aventurado és tu, ó Israel! Quem é como tu, povo salvo pelo SENHOR, o escudo de teu socorro, e a espada da tua excelência? Por isso os teus inimigos serão subjugados, e tu pisarás sobre as suas alturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 1, 'E Moisés subiu dos campos de Moabe ao monte Nebo, ao cume de Pisga, que está em frente de Jericó; e o SENHOR mostrou-lhe toda a terra de Gileade até Dã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 2, 'E a todo Naftali, e a terra de Efraim e de Manassés, toda a terra de Judá até o mar mais distante;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 3, 'E a parte sul, e a campina, o vale de Jericó, cidade das palmeiras, até Zoar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 4, 'E disse-lhe o SENHOR: Esta é a terra de que jurei a Abraão, a Isaque, e a Jacó, dizendo: À tua descendência a darei. Eu a fiz ver com teus olhos, mas não passarás ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 5, 'E morreu ali Moisés, servo do SENHOR, na terra de Moabe, conforme o dito do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 6, 'E enterrou-o no vale, em terra de Moabe, em frente de Bete-Peor; e ninguém sabe seu sepulcro até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 7, 'E era Moisés de idade de cento e vinte anos quando morreu: seus olhos nunca se escureceram, nem perdeu o seu vigor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 8, 'E choraram os filhos de Israel a Moisés nos campos de Moabe trinta dias: E assim se cumpriram os dias do choro do luto de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 9, 'E Josué filho de Num foi cheio de espírito de sabedoria, porque Moisés havia posto suas mãos sobre ele: e os filhos de Israel lhe obedeceram, e fizeram como o SENHOR mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 10, 'E nunca mais se levantou profeta em Israel como Moisés, a quem haja conhecido o SENHOR face a face;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 11, 'Em todos os sinais e prodígios que lhe enviou o SENHOR a fazer em terra do Egito a Faraó, e a todos os seus servos, e a toda sua terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 34, 12, 'E em toda aquela mão poderosa, e em todo o grande espanto que Moisés causou à vista de todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 1, 'E aconteceu depois da morte de Moisés servo do SENHOR, que o SENHOR falou a Josué filho de Num, assistente de Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 2, 'Meu servo Moisés é morto: levanta-te, pois, agora, e passa este Jordão, tu e todo este povo, à terra que eu lhes dou aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 3, 'Eu vos entreguei, como o disse a Moisés, todo lugar que pisar a planta de vosso pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 4, 'Desde o deserto e este Líbano até o grande rio Eufrates, toda a terra dos heteus até o grande mar do ocidente, será vosso termo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 5, 'Ninguém poderá resistir a ti em todos os dias de tua vida: como eu fui com Moisés, serei contigo; não te deixarei, nem te desampararei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 6, 'Esforça-te e sê valente: porque tu repartirás a este povo por herança a terra, da qual jurei a seus pais que a daria a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 7, 'Somente te esforces, e sejas muito valente, para cuidar de fazer conforme toda a lei que meu servo Moisés te mandou: não te apartes dela nem à direita nem à esquerda, para que sejas próspero em todas as coisas que empreenderes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 8, 'O livro desta lei nunca se apartará de tua boca: antes de dia e de noite meditarás nele, para que guardes e faças conforme tudo o que nele está escrito: porque então farás prosperar teu caminho, e tudo te sairá bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 9, 'Olha que te mando que te esforces e sejas valente: não temas nem desmaies, porque o SENHOR teu Deus será contigo onde quer que fores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 10, 'E Josué mandou aos oficiais do povo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 11, 'Passai por meio do acampamento, e mandai ao povo, dizendo: Abastecei-vos de comida; porque dentro de três dias passareis o Jordão, para que entreis a possuir a terra que o SENHOR vosso Deus vos dá para que a possuais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 12, 'Também falou Josué aos rubenitas e gaditas, e à meia tribo de Manassés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 13, 'Lembrai-vos da palavra que Moisés, servo do SENHOR, vos mandou dizendo: o SENHOR vosso Deus vos deu repouso, e vos deu esta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 14, 'Vossas mulheres e vossos meninos e vossas animais, ficarão na terra que Moisés vos deu desta parte do Jordão; mas vós, todos os valentes e fortes, passareis armados diante de vossos irmãos, e lhes ajudareis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 15, 'Até tanto que o SENHOR tenha dado repouso a vossos irmãos como a vós, e que eles também possuam a terra que o SENHOR vosso Deus lhes dá: e depois voltareis vós à terra de vossa herança, a qual Moisés servo do SENHOR vos deu, desta parte do Jordão até o oriente; e a possuireis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 16, 'Então responderam a Josué, dizendo: Nós faremos todas as coisas que nos mandaste, e iremos aonde quer que nos mandares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 17, 'Da maneira que obedecemos a Moisés em todas as coisas, assim obedeceremos a ti: somente o SENHOR teu Deus seja contigo, como foi com Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 1, 18, 'Qualquer um que for rebelde ao teu mandamento, e não obedecer às tuas palavras em todas as coisas que lhe mandares, que morra; somente que te esforces, e sejas valente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 1, 'E Josué, filho de Num, enviou desde Sitim dois espias secretamente, dizendo-lhes: Andai, reconhecei a terra, e a Jericó. Os quais foram, e entraram em casa de uma mulher prostituta que se chamava Raabe, e passaram a noite ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 2, 'E foi dado aviso ao rei de Jericó, dizendo: Eis que homens dos filhos de Israel vieram aqui esta noite a espiar a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 3, 'Então o rei de Jericó, enviou a dizer a Raabe: Tira fora os homens que vieram a ti, e entraram em tua casa; porque vieram a espiar toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 4, 'Mas a mulher havia tomado os dois homens, e os havia escondido; e disse: Verdade que homens vieram a mim, mas não soube de onde eram:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 5, 'E ao fechar-se a porta, sendo já escuro, esses homens saíram, e não sei para onde se foram: segui-os depressa, que os alcançareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 6, 'Mas ela os havia feito subir ao terraço, e havia os escondido entre talos de linho que naquele terraço tinha posto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 7, 'E os homens foram atrás eles pelo caminho do Jordão, até os vaus: e a porta foi fechada depois que saíram os que atrás eles iam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 8, 'Mas antes que eles dormissem, ela subiu a eles ao terraço, e disse-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 9, 'Eu sei que o SENHOR vos deu esta terra; porque o temor de vós caiu sobre nós, e todos os moradores desta terra estão apavorados por causa de vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 10, 'Porque ouvimos que o SENHOR fez secar as águas do mar Vermelho diante de vós, quando saístes do Egito, e o que fizestes aos dois reis pelos amorreus que estavam da parte dali do Jordão, a Seom e a Ogue, aos quais destruístes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 11, 'Ouvindo isto, desmaiou nosso coração; nem restou mais espírito em alguém por causa de vós: porque o SENHOR vosso Deus é Deus acima nos céus e abaixo na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 12, 'Rogo-vos, pois, agora, me jureis pelo SENHOR, que como fiz misericórdia convosco, assim a fareis vós com a casa de meu pai, do qual me dareis um sinal certo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 13, 'E que salvareis a vida a meu pai e a minha mãe, e a meus irmãos e irmãs, e a todo o que for seu; e que livrareis nossas vidas da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 14, 'E eles lhe responderam: Nossa vida esteja pela vossa até a morte, se não denunciardes este nosso negócio; e quando o SENHOR houver nos dado a terra, nós a trataremos com misericórdia e fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 15, 'Então ela os fez descer com uma corda pela janela; porque sua casa estava à parede do muro, e ela vivia no muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 16, 'E disse-lhes: Marchai-vos ao monte, porque os que foram atrás vós não vos encontrem; e estai escondidos ali três dias, até que os que vos seguem tenham voltado; e depois vos ireis vosso caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 17, 'E eles lhe disseram: Nós seremos desobrigados deste juramento com que nos hás conjurado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 18, 'Eis que, quando nós entrarmos na terra, tu atarás este cordão de escarlate à janela pela qual nos fizeste descer: e tu juntarás em tua casa teu pai e tua mãe, teus irmãos e toda a família de teu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 19, 'Qualquer um que sair fora das portas de tua casa, seu sangue será sobre sua cabeça, e nós sem culpa. Mas qualquer um que estiver em casa contigo, seu sangue será sobre nossa cabeça, se mão o tocar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 20, 'E se tu denunciares este nosso negócio, nós seremos desobrigados deste teu juramento com que nos fizeste jurar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 21, 'E ela respondeu: Seja assim como dissestes. Logo os despediu, e se foram: e ela atou o cordão de escarlate à janela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 22, 'E caminhando eles, chegaram ao monte, e estiveram ali três dias, até que os que os seguiam se houvessem voltado: e os que os seguiram, buscaram por todo aquele caminho, mas não os acharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 23, 'E voltando-se os dois homens, desceram do monte, e passaram, e vieram a Josué filho de Num, e contaram-lhe todas as coisas que lhes haviam acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 2, 24, 'E disseram a Josué: O SENHOR entregou toda esta terra em nossas mãos; e também todos os moradores desta terra estão apavorados por nossa causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 1, 'E levantou-se Josué de manhã, e partiram de Sitim, e vieram até o Jordão, ele e todos os filhos de Israel, e repousaram ali antes que passassem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 2, 'E passados três dias, os oficiais atravessaram por meio do acampamento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 3, 'E mandaram ao povo, dizendo: Quando virdes a arca do pacto do SENHOR vosso Deus, e os sacerdotes e levitas que a levam, vós partireis de vosso lugar, e marchareis atrás dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 4, 'Porém entre vós e ela haja distância como da medida de dois mil côvados: e não vos aproximareis dela, a fim de que saibais o caminho por onde haveis de ir: porquanto vós não passastes antes de agora por este caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 5, 'E Josué disse ao povo: Santificai-vos, porque o SENHOR fará amanhã entre vós maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 6, 'E falou Josué aos sacerdotes, dizendo: Tomai a arca do pacto, e passai diante do povo. E eles tomaram a arca do pacto, e foram diante do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 7, 'Então o SENHOR disse a Josué: Desde este dia começarei a fazer-te grande diante dos olhos de todo Israel, para que entendam que como fui com Moisés, assim serei contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 8, 'Tu, pois, mandarás aos sacerdotes que levam a arca do pacto, dizendo: Quando houverdes entrado até a borda da água do Jordão, parareis no Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 9, 'E Josué disse aos filhos de Israel: Achegai-vos aqui, e escutai as palavras do SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 10, 'E acrescentou Josué: Em isto conhecereis que o Deus vivente está em meio de vós, e que ele lançará de diante de vós aos cananeus, e aos heteus, e aos heveus, e aos perizeus, e aos gergeseus, e aos amorreus, e aos jebuseus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 11, 'Eis que, a arca do pacto do Dominador de toda a terra passa o Jordão diante de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 12, 'Tomai, pois, agora doze homens das tribos de Israel, de cada tribo um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 13, 'E quando as plantas dos pés dos sacerdotes que levam a arca do SENHOR Dominador de toda a terra, forem assentadas sobre as águas do Jordão, as águas do Jordão se partirão: porque as águas que vem de acima se deterão em um amontoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 14, 'E aconteceu que, partindo o povo de suas tendas para passar o Jordão, e os sacerdotes diante do povo levando a arca do pacto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 15, 'Quando os que levavam a arca chegaram no Jordão, assim como os pés dos sacerdotes que levavam a arca foram molhados à beira da água, (porque o Jordão costuma transbordar sobre todas as suas margens todo aquele tempo da colheita,)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 16, 'As águas que vinham de cima pararam, e amontoaram-se bem longe, na cidade de Adã, que está ao lado de Zaretã; e as que desciam ao mar das planícies, ao mar Salgado, esgotaram-se e foram totalmente interrompidas; e o povo passou em frente de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 3, 17, 'Mas os sacerdotes que levavam a arca do pacto do SENHOR, ficaram firmes em seco, no meio do Jordão, e todo Israel passou em seco, até que todo o povo acabou de passar o Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 1, 'E quando toda a nação acabou de passar o Jordão, o SENHOR falou a Josué, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 2, 'Tomai do povo doze homens, de cada tribo um,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 3, 'E mandai-lhes, dizendo: Tomai-vos daqui do meio do Jordão, do lugar de onde estão firmes os pés dos sacerdotes, doze pedras, as quais passareis convosco, e as assentareis no alojamento de onde haveis de passar a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 4, 'Então Josué chamou aos doze homens, os quais ele havia ordenado dentre os filhos de Israel, de cada tribo um;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 5, 'E disse-lhes Josué: Passai diante da arca do SENHOR vosso Deus ao meio do Jordão; e cada um de vós tome uma pedra sobre seu ombro, conforme ao número das tribos dos filhos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 6, 'Para que isto seja sinal entre vós; e quando vossos filhos perguntarem a seus pais amanhã, dizendo: “Que vos significam estas pedras?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 7, 'Então vós lhes respondereis: “As águas do Jordão foram interrompidas diante da arca do pacto do SENHOR; quando ela passou pelo Jordão, as águas do Jordão se separaram; e estas pedras serão por memorial aos filhos de Israel para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 8, 'E os filhos de Israel o fizeram assim como Josué havia lhes mandado, e levantaram doze pedras do meio do Jordão, como o SENHOR havia dito a Josué, conforme o número das tribos dos filhos de Israel; e levaram-nas consigo ao alojamento, e ali as puseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 9, 'Josué também levantou doze pedras no meio do Jordão, no lugar onde estiveram os pés dos sacerdotes que levavam a arca do pacto; e ali estão até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 10, 'Pois os sacerdotes que levavam a arca ficaram parados no meio do Jordão, até que se cumpriu tudo o que o SENHOR havia mandado a Josué dizer ao povo, conforme tudo quanto Moisés havia ordenado a Josué; e o povo apressou-se e passou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 11, 'E sucedeu quando todo o povo acabou de passar, então passaram a arca do SENHOR, e os sacerdotes, na presença do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 12, 'Também os filhos de Rúben, os filhos de Gade, e a meia tribo de Manassés, passaram armados diante dos filhos de Israel, como Moisés havia lhes dito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 13, 'cerca de quarenta mil homens prontamente armados passaram ó diante do SENHOR para a batalha, às campina de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 14, 'Naquele dia o SENHOR engrandeceu Josué à vista de todo Israel; e temeram-no, como haviam temido a Moisés, todos os dias de sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 15, 'E o SENHOR falou a Josué, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 16, '“Manda os sacerdotes que levam a arca do testemunho, que subam do Jordão”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 17, 'E Josué mandou os sacerdotes, dizendo: “Subi do Jordão”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 18, 'E aconteceu que quando os sacerdotes que levavam a arca do pacto do SENHOR subiram do meio do Jordão, e as plantas dos pés dos sacerdotes estiveram em seco, as águas do Jordão voltaram ao seu lugar, correndo como antes sobre todas as suas margens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 19, 'E o povo subiu do Jordão no dia dez do mês primeiro, e assentaram o acampamento em Gilgal, ao lado oriental de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 20, 'E Josué erigiu em Gilgal as doze pedras que haviam trazido do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 21, 'E falou aos filhos de Israel, dizendo: Quando amanhã perguntarem vossos filhos a seus pais, e disserem: Que vos significam estas pedras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 22, 'Declarareis a vossos filhos, dizendo: Israel passou em seco por este Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 23, 'Porque o SENHOR vosso Deus secou as águas do Jordão diante de vós, até que havíeis passado, à maneira que o SENHOR vosso Deus o havia feito no mar Vermelho, ao qual secou diante de nós até que passamos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 4, 24, 'Para que todos os povos da terra conheçam a mão do SENHOR, que é forte; para que temais ao SENHOR vosso Deus todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 1, 'E quando todos os reis dos amorreus, que estavam da outra parte do Jordão ao ocidente, e todos os reis dos cananeus, que estavam próximos do mar, ouviram como o SENHOR havia secado as águas do Jordão diante dos filhos de Israel até que passaram, desfaleceu seu coração, e não houve mais espírito neles diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 2, 'Naquele tempo o SENHOR disse a Josué: Faze-te facas afiadas, e volta a circuncidar a segunda vez aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 3, 'E Josué se fez facas afiadas, e circuncidou aos filhos de Israel no monte dos prepúcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 4, 'Esta é a causa pela qual Josué os circuncidou: todo aquele povo que havia saído do Egito, os homens, todos os homens de guerra, haviam morrido no deserto pelo caminho, depois que saíram do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 5, 'Porque todos os do povo que haviam saído, estavam circuncidados: mas todo aquele povo que havia nascido no deserto pelo caminho, depois que saíram do Egito, não estavam circuncidados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 6, 'Porque os filhos de Israel andaram pelo deserto por quarenta anos, até que toda a gente dos homens de guerra que haviam saído do Egito foi consumida, porquanto não obedeceram à voz do SENHOR; pelo qual o SENHOR lhes jurou que não lhes deixaria ver a terra, da qual o SENHOR havia jurado a seus pais que não as daria, terra que flui leite e mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 7, 'E os filhos deles, que ele havia feito suceder em seu lugar, Josué os circuncidou; pois eram incircuncisos, porque não haviam sido circuncidados pelo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 8, 'E quando acabaram de circuncidar toda a gente, ficaram no mesmo lugar no acampamento, até que sararam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 9, 'E o SENHOR disse a Josué: Hoje tirei de vós a humilhação do Egito: pelo qual o nome daquele lugar foi chamado Gilgal, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 10, 'E os filhos de Israel assentaram o acampamento em Gilgal, e celebraram a páscoa aos catorze dias do mês, pela tarde, nas planícies de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 11, 'E ao outro dia da páscoa comeram do fruto da terra os pães sem levedura, e no mesmo dia espigas novas tostadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 12, 'E o maná cessou o dia seguinte, desde que começaram a comer do fruto da terra: e os filhos de Israel nunca mais tiveram maná, mas sim que comeram dos frutos da terra de Canaã aquele ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 13, 'E estando Josué próximo de Jericó, levantou seus olhos, e viu um homem que estava diante dele, o qual tinha uma espada nua em sua mão. E Josué indo até ele, lhe disse: És dos nossos, ou de nossos inimigos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 14, 'E ele respondeu: Não; mas sim Príncipe do exército do SENHOR, agora vim. Então Josué prostrando-se sobre seu rosto em terra o adorou; e disse-lhe: Que diz meu Senhor a seu servo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 5, 15, 'E o Príncipe do exército do SENHOR respondeu a Josué: Tira teus sapatos de teus pés; porque o lugar onde estás é santo. E Josué o fez assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 1, 'Porém Jericó estava fechada, bem fechada, por causa dos filhos de Israel: ninguém entrava, nem saía.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 2, 'Mas o SENHOR disse a Josué: Olha, eu entreguei em tua mão a Jericó e a seu rei, com seus homens de guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 3, 'Cercareis, pois, a cidade todos os homens de guerra, indo ao redor da cidade uma vez: e isto fareis seis dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 4, 'E sete sacerdotes levarão sete trombetas de chifres de carneiros diante da arca; e ao sétimo dia dareis sete voltas à cidade, e os sacerdotes tocarão as trombetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 5, 'E quando tocarem prolongadamente a trombeta de carneiro, assim que ouvirdes o som da trombeta, todo aquele povo gritará a grande voz, e o muro da cidade cairá debaixo de si: então o povo subirá cada um em frente de si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 6, 'E chamando Josué filho de Num aos sacerdotes, lhes disse: Levai a arca do pacto, e sete sacerdotes levem trombetas de chifres de carneiros diante da arca do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 7, 'E disse ao povo: Passai, e rodeai a cidade; e os que estão armados passarão diante da arca do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 8, 'E assim que Josué falou ao povo, os sete sacerdotes, levando as sete trombetas de chifres de carneiros, passaram diante da arca do SENHOR, e tocaram as trombetas: e a arca do pacto do SENHOR os seguia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 9, 'E os homens armados iam diante dos sacerdotes que tocavam as trombetas, e a gente reunida ia detrás da arca, andando e tocando trombetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 10, 'E Josué mandou ao povo, dizendo: Vós não dareis grito, nem se ouvirá vossa voz, nem sairá palavra de vossa boca, até o dia que eu vos diga: Gritai: então dareis grito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 11, 'Então a arca do SENHOR deu uma volta ao redor da cidade, e vieram-se ao acampamento, no qual tiveram a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 12, 'E Josué se levantou de manhã, e os sacerdotes tomaram a arca do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 13, 'E os sete sacerdotes, levando as sete trombetas de chifres de carneiros, foram diante da arca do SENHOR, andando sempre e tocando as trombetas; e os armados iam diante deles, e a gente reunida ia detrás da arca do SENHOR, andando e tocando l'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 14, 'Assim deram outra volta à cidade o segundo dia, e voltaram ao acampamento: desta maneira fizeram por seis dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 15, 'E ao sétimo dia levantaram-se quando subia a alva, e deram volta à cidade da mesma maneira sete vezes: somente este dia deram volta ao redor dela sete vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 16, 'E quando os sacerdotes tocaram as trombetas pela sétima vez, Josué disse ao povo: Dai grito, porque o SENHOR vos entregou a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 17, 'Mas a cidade será anátema ao SENHOR, ela com todas as coisas que estão nela: somente Raabe a prostituta viverá, com todos os que estiverem em casa com ela, porquanto escondeu os mensageiros que enviamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 18, 'Porém guardai-vos vós do anátema, que nem toqueis, nem tomeis alguma coisa do anátema, porque não façais anátema o acampamento de Israel, e o perturbeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 19, 'Mas toda a prata, e o ouro, e vasos de bronze e de ferro, seja consagrado ao SENHOR, e venha ao tesouro do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 20, 'Então o povo deu grito, e os sacerdotes tocaram as trombetas: e aconteceu que quando o povo ouviu o som da trombeta, deu o povo grito com grande barulho, e o muro caiu verticalmente. O povo subiu logo à cidade, cada um em frente de si, e tomaram-na.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 21, 'E destruíram tudo o que na cidade havia; homens e mulheres, moços e anciãos, até os bois, e ovelhas, e asnos, a fio de espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 22, 'Mas Josué disse aos dois homens que haviam reconhecido a terra: Entrai em casa da mulher prostituta, e fazei sair dali à mulher, e a tudo o que for seu, como o jurastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 23, 'E os rapazes espias entraram, e tiraram a Raabe, e a seu pai, e a sua mãe, e a seus irmãos, e todo o que era seu; e também tiraram a toda sua parentela, e puseram-nos fora do acampamento de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 24, 'E consumiram com fogo a cidade, e tudo o que nela havia: somente puseram no tesouro da casa do SENHOR a prata, e o ouro, e os vasos de bronze e de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 25, 'Mas Josué salvou a vida a Raabe a prostituta, e à casa de seu pai, e a tudo o que ela tinha: e habitou ela entre os israelitas até hoje; porquanto escondeu os mensageiros que Josué enviou a reconhecer a Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 26, 'E naquele tempo Josué lhes juramentou dizendo: Maldito diante do SENHOR o homem que se levantar e reedificar esta cidade de Jericó. Em seu primogênito lance seus alicerces, e em seu menor assente suas portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 6, 27, 'Foi, pois, o SENHOR com Josué, e seu nome se divulgou por toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 1, 'Porém os filhos de Israel cometeram transgressão no anátema: porque Acã, filho de Carmi, filho de Zabdi, filho de zerá, da tribo de Judá, tomou do anátema; e a ira do SENHOR se acendeu contra os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 2, 'E Josué enviou homens desde Jericó a Ai, que estava junto a Bete-Áven até o oriente de Betel; e falou-lhes dizendo: Subi, e reconhecei a terra. E eles subiram, e reconheceram a Ai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 3, 'E voltando a Josué, disseram-lhe: Não suba todo aquele povo, mas subam como dois mil ou como três mil homens, e tomarão a Ai: não canses a todo aquele povo ali, porque são poucos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 4, 'E subiram ali do povo como três mil homens, os quais fugiram diante dos de Ai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 5, 'E os de Ai feriram deles como trinta e seis homens, e seguiram-nos desde a porta até Sebarim, e os feriram na descida: pelo que se dissolveu o coração do povo, e veio a ser como água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 6, 'Então Josué rasgou suas roupas, e prostrou-se em terra sobre seu rosto diante da arca do SENHOR até à tarde, ele e os anciãos de Israel; e lançaram pó sobre suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 7, 'E Josué disse: Ah, Senhor DEUS! Por que fizeste passar a este povo o Jordão, para entregar-nos nas mãos dos amorreus, que nos destruam? Antes nos tivéssemos ficado da outra parte do Jordão!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 8, 'Ai Senhor! Que direi, já que Israel virou as costas diante de seus inimigos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 9, 'Porque os cananeus e todos os moradores da terra ouvirão, e nos cercarão, e apagarão nosso nome de sobre a terra: então que farás tu a teu grande nome?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 10, 'E o SENHOR disse a Josué: Levanta-te; por que te prostras assim sobre teu rosto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 11, 'Israel pecou, e ainda quebrantou meu pacto que eu lhes havia mandado; pois ainda tomaram do anátema, e até furtaram, e também mentiram, e ainda o guardaram entre seus utensílios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 12, 'Por isto os filhos de Israel não poderão estar diante de seus inimigos, mas sim que diante de seus inimigos virarão as costas; porquanto vieram a ser anátema: nem serei mais convosco, se não destruirdes o anátema do meio de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 13, 'Levanta-te, santifica ao povo, e dize: Santificai-vos para amanhã, porque o SENHOR o Deus de Israel diz assim: Anátema há em meio de ti, Israel; não poderás estar diante de teus inimigos, até tanto que tenhais tirado o anátema do meio de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 14, 'Vós vos achegareis, pois, amanhã por vossas tribos; e a tribo que o SENHOR tomar, se achegará por suas famílias; e a família que o SENHOR tomar, se achegará por suas casas; e a casa que o SENHOR tomar, se achegará pelos homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 15, 'E o que for colhido no anátema, será queimado a fogo, ele e tudo o que tem, porquanto quebrantou o pacto do SENHOR, e cometeu maldade em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 16, 'Josué, pois, levantando-se de manhã, fez achegar a Israel por suas tribos; e foi tomada a tribo de Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 17, 'E fazendo achegar a tribo de Judá, foi tomada a família dos de Zerá; fazendo logo achegar a família dos de Zerá pelos homens, foi tomado Zabdi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 18, 'E fez achegar sua casa pelos homens, e foi tomado Acã, filho de Carmi, filho de Zabdi, filho de zerá, da tribo de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 19, 'Então Josué disse a Acã: Filho meu, dá glória agora ao SENHOR o Deus de Israel, e dá-lhe louvor, e declara-me agora o que fizeste; não me o encubras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 20, 'E Acã respondeu a Josué, dizendo: Verdadeiramente eu pequei contra o SENHOR o Deus de Israel, e fiz assim e assim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 21, 'Que vi entre os despojos um manto babilônico muito bom, e duzentos siclos de prata, e uma barra de ouro de peso de cinquenta siclos; o qual cobicei, e tomei: e eis que está escondido debaixo da terra no meio de minha tenda, e o dinheiro debaixo dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 22, 'Josué então enviou mensageiros, os quais foram correndo à tenda; e eis que estava escondido em sua tenda, e o dinheiro debaixo disso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 6, 'Josué', 'Js', 7, 23, 'E tomando-o do meio da tenda, trouxeram-no a Josué e a todos os filhos de Israel, e puseram-no diante do SENHOR.')
